import java.util.*;

public class Main {
    static class Edge {
        int src, dst;
        int cap;
        long cost;
        Edge rev;

        Edge(int src, int dst, int cap, long cost, Edge rev) {
            this.src = src;
            this.dst = dst;
            this.cap = cap;
            this.cost = cost;
            this.rev = rev;
        }
    }

    static class MinCostFlow {
        ArrayList<ArrayList<Edge>> adj;
        long minCost, totalCost;
        int[] supp;
        long[] ptnl, dist;
        Edge[] last;
        int n; // number of original nodes (excluding source/sink)

        MinCostFlow(int n) {
            this.n = n;
            int size = n + 2;
            adj = new ArrayList<>(size);
            for (int i = 0; i < size; i++) adj.add(new ArrayList<>());
            minCost = 0;
            totalCost = 0;
            supp = new int[size];
            ptnl = new long[size];
            dist = new long[size];
            last = new Edge[size];
        }

        int size() { return n; }

        void addEdge(int src, int dst, int cap, long cost) {
            if (cap <= 0) return;
            if (cost < 0) {
                supp[src] -= cap;
                supp[dst] += cap;
                minCost += cap * cost;
                totalCost -= cap * cost;
                // add reverse edge with positive cost
                Edge a = new Edge(dst, src, cap, -cost, null);
                Edge b = new Edge(src, dst, 0, cost, null);
                a.rev = b;
                b.rev = a;
                adj.get(dst).add(a);
                adj.get(src).add(b);
            } else {
                totalCost += cap * cost;
                Edge a = new Edge(src, dst, cap, cost, null);
                Edge b = new Edge(dst, src, 0, -cost, null);
                a.rev = b;
                b.rev = a;
                adj.get(src).add(a);
                adj.get(dst).add(b);
            }
        }

        void supply(int node, int vol) {
            supp[node] += vol;
        }

        boolean dijkstra(int src, int dst) {
            long INF = totalCost + 1;
            Arrays.fill(dist, INF);
            dist[src] = 0;
            PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
            pq.offer(new long[]{0, src});
            while (!pq.isEmpty()) {
                long[] top = pq.poll();
                long ndist = -top[0];
                int now = (int) top[1];
                if (ndist != dist[now]) continue;
                ptnl[now] += ndist;
                dist[now] = -1; // mark as processed
                for (Edge e : adj.get(now)) {
                    if (dist[e.dst] == -1 || e.cap == 0) continue;
                    long newDist = ptnl[now] + e.cost - ptnl[e.dst];
                    if (dist[e.dst] > newDist) {
                        dist[e.dst] = newDist;
                        last[e.dst] = e;
                        pq.offer(new long[]{-newDist, e.dst});
                    }
                }
            }
            return dist[dst] == -1; // true if dst is processed (i.e., reachable)
        }

        boolean solve() {
            int src = n;
            int dst = n + 1;
            int flow = 0;
            int suppSum = 0;
            for (int i = 0; i < n + 2; i++) {
                suppSum += supp[i];
                if (supp[i] > 0) {
                    flow += supp[i];
                    addEdge(src, i, supp[i], 0);
                } else if (supp[i] < 0) {
                    addEdge(i, dst, -supp[i], 0);
                }
                supp[i] = 0;
            }
            if (suppSum != 0) return false;
            while (flow > 0) {
                if (!dijkstra(src, dst)) return false;
                int resid = flow;
                for (int node = dst; node != src; node = last[node].src) {
                    resid = Math.min(resid, last[node].cap);
                }
                flow -= resid;
                minCost += ptnl[dst] * resid;
                for (int node = dst; node != src; node = last[node].src) {
                    last[node].cap -= resid;
                    last[node].rev.cap += resid;
                }
            }
            return true;
        }

        long optimal() {
            solve();
            return minCost;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();
        int tlim = 105;
        MinCostFlow mcf = new MinCostFlow(6100);
        for (int i = 0; i < k; i++) {
            int j = sc.nextInt() - 1;
            mcf.supply(j, 1);
        }
        for (int i = 0; i < m; i++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            for (int t = 0; t < tlim; t++) {
                int nu = u + n;
                int nv = v + n;
                for (int x = 0; x < k; x++) {
                    mcf.addEdge(u, nv, 1, c + d * (2L * x + 1));
                    mcf.addEdge(v, nu, 1, c + d * (2L * x + 1));
                }
                u = nu;
                v = nv;
            }
        }
        for (int i = 1; i < n; i++) {
            for (int t = 0; t < tlim; t++) {
                mcf.addEdge(n * t + i, n * (t + 1) + i, k, c);
            }
        }
        int dst = mcf.size() - 1;
        mcf.supply(dst, -k);
        for (int t = 0; t <= tlim; t++) {
            mcf.addEdge(t * n, dst, k, 0);
        }
        System.out.println(mcf.optimal());
        sc.close();
    }
}
